import{_ as o,r as s,o as p,c as l,e as t,a as r,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Introduction - October CMS - 3.x","titleTemplate":false,"description":"October CMS ships with a simple and lean AJAX framework.","frontmatter":{"subtitle":"October CMS ships with a simple and lean AJAX framework."},"headers":[{"level":2,"title":"Including the Framework","slug":"including-the-framework","link":"#including-the-framework","children":[{"level":3,"title":"Extra Features","slug":"extra-features","link":"#extra-features","children":[]}]},{"level":2,"title":"How AJAX Requests Work","slug":"how-ajax-requests-work","link":"#how-ajax-requests-work","children":[]},{"level":2,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/cms/ajax/introduction.md","filePath":"3.x/cms/ajax/introduction.md"}'),c={name:"3.x/cms/ajax/introduction.md"};function u(d,a,h,g,k,m){const n=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[t(n),a[0]||(a[0]=r("h1",null,"Introduction",-1)),t(e),a[1]||(a[1]=i(`<p>October CMS includes an AJAX framework that brings a full suite of capabilities, allowing you to load data from the server without refreshing the browser. The same library can be used in CMS themes and anywhere in the admin panel.</p><p>The AJAX framework comes in two flavors, you may either use <a href="./javascript-api.html">the JavaScript API</a> or <a href="./attributes-api.html">the data attributes API</a>. The data attributes API doesn&#39;t require any JavaScript knowledge to use AJAX with October CMS.</p><h2 id="including-the-framework"><a href="#including-the-framework" class="header-anchor">#</a> Including the Framework</h2><div class="custom-block aside"><p>The AJAX framework is optional in your CMS theme and you can always include your preferred framework instead.</p></div><p>When working with your <a href="./../../cms/themes/themes.html">CMS theme</a>, using the library is as simple as including it with a Twig tag. Place the <code>{% framework %}</code> tag anywhere inside your page or layout. This adds a reference to the October CMS frontend JavaScript library, for example.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="extra-features"><a href="#extra-features" class="header-anchor">#</a> Extra Features</h3><p>The <code>{% framework %}</code> tag supports an optional <strong>extras</strong> parameter that includes additional StyleSheet and JavaScript files, for extra features including <a href="./../features/validation.html">form validation</a>, <a href="./../features/loaders.html">loading indicators</a>, and <a href="./../features/flash-messages.html">flash messages</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You may also include the <strong>turbo</strong> parameter to enable <a href="./turbo-router.html">turbo-charged routing</a> on every page.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras turbo <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="how-ajax-requests-work"><a href="#how-ajax-requests-work" class="header-anchor">#</a> How AJAX Requests Work</h2><p>A page can issue an AJAX request either prompted by data attributes or by using JavaScript. Each request invokes an <strong>event handler</strong> -- also called an <a href="./handlers.html">AJAX handler</a> -- on the server and can update page elements using partials. AJAX requests work best with forms, since the form data is automatically sent to the server. Here is request workflow:</p><ol><li>The client browser issues an AJAX request by providing the handler name and other optional parameters.</li><li>The server finds the <a href="./handlers.html">AJAX handler</a> and executes it.</li><li>The handler executes the required business logic and updates the environment by injecting page variables.</li><li>The server <a href="./update-partials.html">renders partials</a> requested by the client with the <code>update</code> option.</li><li>The server sends the response, containing the rendered partials markup.</li><li>The client-side framework updates page elements with the partials data received from the server.</li></ol><h2 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h2><p>Below is a simple example that uses the data attributes API to define an AJAX enabled form. The form will issue an AJAX request to the <strong>onTest</strong> handler and requests that the result container be updated with the <strong>mypartial</strong> partial markup.</p><div class="custom-block tip"><p>The form data for <code>value1</code> and <code>value2</code> are automatically sent with the AJAX request.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- AJAX enabled form --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onTest<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mypartial: &#39;#myDiv&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Input two values --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span> + <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Action button --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Calculate<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- Result container --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The <strong>mypartial</strong> partial contains markup that reads the <code>result</code> variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The answer is <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <strong>onTest</strong> handler method accessed the form data using the <code>input</code> <a href="./../../extend/services/helpers.html">helper method</a> and the result is passed to the <code>result</code> page variable.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The example could be read like this: &quot;When the form is submitted, issue an AJAX request to the <strong>onTest</strong> handler. When the handler finishes, render the <strong>mypartial</strong> partial and inject its contents to the <strong>#myDiv</strong> element.&quot;</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./javascript-api.html">JavaScript API</a></li><li><a href="./attributes-api.html">Data Attributes API</a></li></ul></div>`,24))])}const v=o(c,[["render",u]]);export{w as __pageData,v as default};
